<template>
  <c311-app-shell title="City 311 administration" main-id="c311-admin-main">
    <template #nav><c311-main-nav :items="navItems" aria-label="Administration navigation" /></template>
    <c311-data-state v-if="state !== 'populated'" :state="state" :error="error" @retry="load" />
    <template v-else>
      <h1 class="h3 mb-3">City 311 administration</h1>
      <div v-if="message" class="alert alert-success" role="status">{{ message }}</div>
      <c311-error-summary :errors="formErrors" title="Review this operation" />
      <section v-if="identity" class="mb-4" aria-labelledby="identity-heading">
        <h2 id="identity-heading" class="h4">Identity configuration</h2>
        <form @submit.prevent="saveIdentity"><div class="form-check"><input id="oidc-enabled" v-model="identity.oidc_enabled" class="form-check-input" type="checkbox"><label for="oidc-enabled" class="form-check-label">Enable OpenID Connect</label></div><div class="form-check"><input id="saml-enabled" v-model="identity.saml_enabled" class="form-check-input" type="checkbox"><label for="saml-enabled" class="form-check-label">Enable SAML</label></div><p class="text-muted mt-2">OIDC secret configured: {{ identity.oidc_client_secret_configured ? 'Yes' : 'No' }}</p><button class="btn btn-primary" type="submit" :disabled="busy">Save identity configuration</button></form>
      </section>
      <section v-if="integrations !== null" class="mb-4" aria-labelledby="integrations-heading"><h2 id="integrations-heading" class="h4">Integrations</h2><table class="table table-sm"><thead><tr><th>ID</th><th>Kind</th><th>Active</th><th>Secret configured</th><th /></tr></thead><tbody><tr v-for="item in integrations" :key="item.integration_id"><td>{{ item.integration_id }}</td><td>{{ item.kind }}</td><td>{{ item.active ? 'Yes' : 'No' }}</td><td>{{ item.secret_configured ? 'Yes' : 'No' }}</td><td><button class="btn btn-sm btn-outline-primary" type="button" :disabled="busy" @click="toggleIntegration(item)">{{ item.active ? 'Disable' : 'Enable' }}</button><button class="btn btn-sm btn-outline-secondary ml-1" type="button" :disabled="busy" @click="rotateIntegration(item)">Rotate secret</button></td></tr></tbody></table></section>
      <section v-if="branding" class="mb-4" aria-labelledby="branding-heading">
        <h2 id="branding-heading" class="h4">Branding</h2>
        <form @submit.prevent="saveBranding">
          <div class="form-row"><div class="form-group col-md-6"><label for="org-name">Organisation name</label><input id="org-name" v-model.trim="branding.organisation_name" class="form-control"></div><div class="form-group col-md-3"><label for="primary-colour">Primary colour</label><input id="primary-colour" v-model.trim="branding.primary_colour" class="form-control"></div><div class="form-group col-md-3"><label for="accent-colour">Accent colour</label><input id="accent-colour" v-model.trim="branding.accent_colour" class="form-control"></div></div>
          <div class="form-row"><div class="form-group col-md-4"><label for="logo-url">Logo URL</label><input id="logo-url" v-model.trim="branding.logo_url" class="form-control" type="url"></div><div class="form-group col-md-4"><label for="favicon-url">Favicon URL</label><input id="favicon-url" v-model.trim="branding.favicon_url" class="form-control" type="url"></div><div class="form-group col-md-4"><label for="wallpaper-url">Portal wallpaper URL</label><input id="wallpaper-url" v-model.trim="branding.portal_wallpaper_url" class="form-control" type="url"></div></div>
          <div class="form-row"><div class="form-group col-md-4"><label for="login-header">Login header</label><input id="login-header" v-model.trim="branding.login_header" class="form-control"></div><div class="form-group col-md-4"><label for="public-header">Public header</label><input id="public-header" v-model.trim="branding.public_header" class="form-control"></div><div class="form-group col-md-4"><label for="public-footer">Public footer</label><input id="public-footer" v-model.trim="branding.public_footer" class="form-control"></div></div>
          <div class="form-group col-md-4 px-0"><label for="font-family">Font family</label><select id="font-family" v-model="branding.font_family" class="form-control"><option value="System Sans">System Sans</option><option value="Inter">Inter</option><option value="Source Sans 3">Source Sans 3</option></select></div>
          <button class="btn btn-primary" type="submit" :disabled="busy">Save branding</button><button class="btn btn-outline-primary ml-2" type="button" :disabled="busy" @click="previewBranding">Preview</button><button class="btn btn-outline-primary ml-2" type="button" :disabled="busy" @click="loadBrandingVersions">Version history</button><button class="btn btn-outline-primary ml-2" type="button" :disabled="busy" @click="publishBranding">Publish</button>
          <div v-if="brandingVersions.length" class="mt-2"><button v-for="version in brandingVersions" :key="version.version" class="btn btn-sm btn-link" type="button" :disabled="busy" @click="rollbackBranding(version.version)">Restore v{{ version.version }}</button></div>
          <section v-if="brandingPreview" class="border p-3 mt-3" aria-label="Branding preview"><h3 class="h6">Preview</h3><div class="c311-branding-preview-grid"><section v-for="viewport in brandingViewports" :key="viewport.key" class="c311-branding-viewport" :data-c311-branding-preview="viewport.key"><h4 class="h6">{{ viewport.label }}</h4><div class="c311-branding-canvas" :style="{ width: `${viewport.width}px`, fontFamily: brandingPreview.font_family }"><section class="c311-branding-login" data-c311-branding-surface="login"><div class="c311-branding-header" :style="{ backgroundColor: brandingPreview.primary_colour }"><img v-if="brandingPreview.logo_url" :src="brandingPreview.logo_url" :alt="`${brandingPreview.organisation_name} logo`"><strong>{{ brandingPreview.organisation_name }}</strong></div><div class="p-2"><p class="mb-2">{{ brandingPreview.login_header }}</p><button class="btn btn-sm" type="button" :style="{ backgroundColor: brandingPreview.accent_colour }">Sign in</button></div></section><section class="c311-branding-public mt-2" data-c311-branding-surface="public"><div class="c311-branding-header" :style="{ backgroundColor: brandingPreview.primary_colour }"><img v-if="brandingPreview.logo_url" :src="brandingPreview.logo_url" :alt="`${brandingPreview.organisation_name} logo`"><strong>{{ brandingPreview.organisation_name }}</strong></div><div class="p-2"><p class="mb-2">{{ brandingPreview.public_header }}</p><button class="btn btn-sm" type="button" :style="{ backgroundColor: brandingPreview.accent_colour }">Submit a request</button></div><footer class="small p-2">{{ brandingPreview.public_footer }}</footer></section></div></section></div></section>
        </form>
      </section>
      <section v-if="content !== null" class="mb-4" aria-labelledby="content-heading">
        <h2 id="content-heading" class="h4">Public content</h2>
        <div class="form-group"><label for="content-key">Content item</label><select id="content-key" v-model="selectedContentKey" class="form-control" @change="selectContent"><option v-for="item in content" :key="item.content_key" :value="item.content_key">{{ item.content_key }} ({{ item.state }})</option></select></div>
        <form v-if="selectedContent" @submit.prevent="saveContent"><label for="content-body">Sanitized HTML</label><textarea id="content-body" v-model="selectedContent.body" class="form-control" rows="6" /><button class="btn btn-primary mt-2" type="submit" :disabled="busy">Save draft</button><button class="btn btn-outline-primary mt-2 ml-2" type="button" :disabled="busy" @click="previewContent">Preview</button><button class="btn btn-outline-primary mt-2 ml-2" type="button" :disabled="busy" @click="loadContentVersions">Version history</button><button class="btn btn-outline-primary mt-2 ml-2" type="button" :disabled="busy" @click="publishContent">Publish</button><div v-if="contentVersions.length" class="mt-2"><button v-for="version in contentVersions" :key="version.version" class="btn btn-sm btn-link" type="button" :disabled="busy" @click="rollbackContent(version.version)">Restore v{{ version.version }}</button></div><section v-if="contentPreview" class="border p-3 mt-3" aria-label="Content preview"><h3 class="h6">Preview</h3><div v-html="contentPreview.body" /></section></form>
      </section>
      <section class="mb-4" aria-labelledby="help-heading"><h2 id="help-heading" class="h4">Contextual help</h2><div class="form-row"><div class="form-group col-md-5"><label for="help-key">Help item</label><select id="help-key" v-model="help.key" class="form-control" @change="loadHelp"><option v-for="key in helpKeys" :key="key" :value="key">{{ key }}</option></select></div><div class="form-group col-md-2"><label for="help-language">Language</label><select id="help-language" v-model="help.language" class="form-control" @change="loadHelp"><option value="EN">English</option><option value="ES">Español</option><option value="VI">Tiếng Việt</option></select></div></div><form @submit.prevent="saveHelp"><label for="help-body">Help HTML</label><textarea id="help-body" v-model="help.body" class="form-control" rows="4" /><button class="btn btn-primary mt-2" type="submit" :disabled="busy">Save draft</button><button class="btn btn-outline-primary mt-2 ml-2" type="button" :disabled="busy" @click="previewHelp">Preview</button><button class="btn btn-outline-primary mt-2 ml-2" type="button" :disabled="busy" @click="loadHelpVersions">Version history</button><button class="btn btn-outline-primary mt-2 ml-2" type="button" :disabled="busy" @click="publishHelp">Publish</button><div v-if="helpVersions.length" class="mt-2"><button v-for="version in helpVersions" :key="version.version" class="btn btn-sm btn-link" type="button" :disabled="busy" @click="rollbackHelp(version.version)">Restore v{{ version.version }}</button></div><section v-if="helpPreview" class="border p-3 mt-3" aria-label="Help preview"><h3 class="h6">Preview</h3><div v-html="helpPreview.body" /></section></form></section>
      <section v-if="categories !== null" class="mb-4" aria-labelledby="categories-heading">
        <h2 id="categories-heading" class="h4">Contact categories</h2>
        <table class="table table-sm"><thead><tr><th>Code</th><th>English label</th><th>Active</th><th /></tr></thead><tbody><tr v-for="item in categories" :key="item.code"><td>{{ item.code }}</td><td>{{ item.labels.EN }}</td><td>{{ item.active ? 'Yes' : 'No' }}</td><td><button class="btn btn-sm btn-link" type="button" :disabled="busy" @click="editCategory(item)">Edit</button></td></tr></tbody></table>
        <form class="form-row" @submit.prevent="saveCategory"><div class="col-md-3"><label for="category-code">Code</label><input id="category-code" v-model.trim="category.code" class="form-control" :readonly="!!category.originalCode"></div><div class="col-md-3"><label for="category-label">English label</label><input id="category-label" v-model.trim="category.labels.EN" class="form-control"></div><div class="col-md-3"><label for="category-label-es">Spanish label</label><input id="category-label-es" v-model.trim="category.labels.ES" class="form-control"></div><div class="col-md-3"><label for="category-label-vi">Vietnamese label</label><input id="category-label-vi" v-model.trim="category.labels.VI" class="form-control"></div><div class="col-md-2 d-flex align-items-end"><div class="form-check"><input id="category-active" v-model="category.active" class="form-check-input" type="checkbox"><label class="form-check-label" for="category-active">Active</label></div></div><div class="col-md-3 d-flex align-items-end"><button class="btn btn-outline-primary" type="submit" :disabled="busy">{{ category.originalCode ? 'Update category' : 'Add category' }}</button><button v-if="category.originalCode" class="btn btn-link" type="button" :disabled="busy" @click="resetCategory">Cancel</button></div></form>
      </section>
      <section v-if="customFields !== null" class="mb-4" aria-labelledby="fields-heading"><h2 id="fields-heading" class="h4">Custom fields</h2><table class="table table-sm"><thead><tr><th>Key</th><th>Entity</th><th>Type</th><th>Required</th><th>Active</th><th /></tr></thead><tbody><tr v-for="item in customFields" :key="item.key"><td>{{ item.key }}</td><td>{{ item.entity }}</td><td>{{ item.field_type }}</td><td>{{ item.required ? 'Yes' : 'No' }}</td><td>{{ item.active ? 'Yes' : 'No' }}</td><td><button class="btn btn-sm btn-link" type="button" @click="editCustomField(item)">Edit</button></td></tr></tbody></table><form @submit.prevent="saveCustomField"><div class="form-row"><div class="form-group col-md-3"><label for="custom-field-key">Key</label><input id="custom-field-key" v-model.trim="customField.key" class="form-control" :readonly="!!customField.originalKey"></div><div class="form-group col-md-3"><label for="custom-field-entity">Entity</label><select id="custom-field-entity" v-model="customField.entity" class="form-control"><option value="constituent">Constituent</option><option value="service_request">Service request</option></select></div><div class="form-group col-md-3"><label for="custom-field-type">Type</label><select id="custom-field-type" v-model="customField.field_type" class="form-control"><option v-for="type in customFieldTypes" :key="type" :value="type">{{ type }}</option></select></div><div class="form-group col-md-3 d-flex align-items-end"><div class="form-check"><input id="custom-field-required" v-model="customField.required" class="form-check-input" type="checkbox"><label class="form-check-label" for="custom-field-required">Required</label></div><div class="form-check ml-3"><input id="custom-field-active" v-model="customField.active" class="form-check-input" type="checkbox"><label class="form-check-label" for="custom-field-active">Active</label></div></div></div><div class="form-row"><div class="form-group col-md-4"><label for="custom-field-label-en">English label</label><input id="custom-field-label-en" v-model.trim="customField.labels.EN" class="form-control"></div><div class="form-group col-md-4"><label for="custom-field-label-es">Spanish label</label><input id="custom-field-label-es" v-model.trim="customField.labels.ES" class="form-control"></div><div class="form-group col-md-4"><label for="custom-field-label-vi">Vietnamese label</label><input id="custom-field-label-vi" v-model.trim="customField.labels.VI" class="form-control"></div></div><label for="custom-field-default">Default value (JSON)</label><input id="custom-field-default" v-model.trim="customField.defaultValue" class="form-control"><label class="mt-2" for="custom-field-validation">Validation rules (JSON)</label><textarea id="custom-field-validation" v-model.trim="customField.validation" class="form-control" rows="2" /><template v-if="['SINGLE_CHOICE', 'MULTI_CHOICE'].includes(customField.field_type)"><label class="mt-2" for="custom-field-choices">Choices, one per line</label><textarea id="custom-field-choices" v-model="customField.choiceValues" class="form-control" rows="3" /></template><button class="btn btn-outline-primary mt-2" type="submit" :disabled="busy">{{ customField.originalKey ? 'Update field' : 'Create field' }}</button><button v-if="customField.originalKey" class="btn btn-link mt-2" type="button" @click="resetCustomField">Cancel</button></form></section>
      <section v-if="workflows !== null" aria-labelledby="workflow-heading"><h2 id="workflow-heading" class="h4">Workflows</h2><table class="table table-sm"><thead><tr><th>Name</th><th>Trigger</th><th>State</th><th /></tr></thead><tbody><tr v-for="item in workflows" :key="item.workflow_id"><td>{{ item.name }}</td><td>{{ item.trigger }}</td><td>{{ item.active ? 'Active' : 'Inactive' }}</td><td><button class="btn btn-sm btn-outline-primary" type="button" :disabled="busy" @click="toggleWorkflow(item)">{{ item.active ? 'Deactivate' : 'Activate' }}</button></td></tr></tbody></table><p class="text-muted" role="status">{{ executions ? executions.length : 0 }} workflow executions loaded.</p></section>
    </template>
  </c311-app-shell>
</template>

<script>
import { components, c311 } from '@cortezaproject/corteza-vue'
const { C311AppShell, C311DataState, C311ErrorSummary, C311MainNav } = components
const stateForError = c311?.c311StateForError
export default {
  name: 'C311AdminWorkspace', components: { C311AppShell, C311DataState, C311ErrorSummary, C311MainNav },
  data: () => ({ state: 'loading', error: null, busy: false, message: '', formErrors: [], identity: null, integrations: null, branding: null, brandingVersions: [], brandingPreview: null, brandingViewports: [{ key: 'mobile', label: 'Mobile', width: 320 }, { key: 'tablet', label: 'Tablet', width: 768 }, { key: 'desktop', label: 'Desktop', width: 1024 }], content: null, contentVersions: [], contentPreview: null, selectedContentKey: '', selectedContent: null, categories: null, customFields: null, workflows: null, executions: null, category: { code: '', labels: { EN: '', ES: '', VI: '' }, originalCode: '', active: true, version: null }, helpKeys: ['public.request.submit', 'public.status.lookup', 'staff.triage', 'staff.reassign', 'staff.bulk-update', 'workflow.authoring', 'report.creation', 'branding.publication'], help: { key: 'public.request.submit', language: 'EN', body: '', version: null }, helpVersions: [], helpPreview: null, customFieldTypes: ['TEXT', 'INTEGER', 'DECIMAL', 'DATE', 'DATETIME', 'BOOLEAN', 'SINGLE_CHOICE', 'MULTI_CHOICE'], customField: { key: '', originalKey: '', entity: 'service_request', field_type: 'TEXT', labels: { EN: '', ES: '', VI: '' }, defaultValue: '', validation: '', choiceValues: '', required: false, active: true, version: null } }),
  computed: { provider () { return this.$C311?.provider }, navItems () { return [{ route: '/c311/admin', label: 'Administration' }, { route: '/c311/staff/requests', label: 'Requests' }, { route: '/c311', label: 'Public portal' }] } },
  async created () { await this.load(); await this.loadHelp() },
  methods: {
    fail (error) { this.error = error; this.formErrors = [{ field: 'form', code: error?.code || error?.error || 'OPERATION_FAILED', message: error?.message || 'The operation could not be completed.' }] },
    async load () { this.state = 'loading'; this.error = null; const previousKey = this.selectedContentKey; const results = await Promise.allSettled([this.provider.getIdentityConfiguration(), this.provider.listIntegrations({ page_size: 100 }), this.provider.getAdminBranding(), this.provider.listAdminContent({ page_size: 100 }), this.provider.listAdminCategories({ page_size: 100 }), this.provider.listAdminCustomFields({ page_size: 100 }), this.provider.listWorkflows({ page_size: 100 }), this.provider.listWorkflowExecutions({ page_size: 100 })]); const value = (index, fallback) => results[index].status === 'fulfilled' ? results[index].value : fallback; this.identity = value(0, null); const integrations = value(1, null); this.integrations = integrations ? integrations.items || [] : null; this.branding = value(2, null); const content = value(3, null); this.content = content ? content.items || [] : null; const categories = value(4, null); this.categories = categories ? categories.items || [] : null; const customFields = value(5, null); this.customFields = customFields ? customFields.items || [] : null; const workflows = value(6, null); this.workflows = workflows ? workflows.items || [] : null; const executions = value(7, null); this.executions = executions ? executions.items || [] : null; this.selectedContentKey = this.content?.some(item => item.content_key === previousKey) ? previousKey : this.content?.[0]?.content_key || ''; this.selectContent(false); if (results.every(result => result.status === 'rejected')) { this.error = results[0].reason; this.state = stateForError?.(this.error) || 'terminal-error' } else this.state = 'populated' },
    selectContent (resetVersions = true) { const item = this.content.find(value => value.content_key === this.selectedContentKey); this.selectedContent = item ? { ...item } : null; if (resetVersions) { this.contentVersions = []; this.contentPreview = null } },
    async run (operation, message) { if (this.busy) return; this.busy = true; this.formErrors = []; this.message = ''; try { await operation(); this.message = message; await this.load() } catch (error) { this.fail(error) } finally { this.busy = false } },
    saveBranding () { return this.run(() => this.provider.updateBranding(this.branding, { expectedVersion: this.branding.version }), 'Branding draft saved.') },
    previewBranding () { return this.run(async () => { this.brandingPreview = await this.provider.previewBranding(this.branding) }, 'Branding preview generated.') },
    loadBrandingVersions () { return this.run(async () => { const page = await this.provider.listBrandingVersions({ page_size: 20 }); this.brandingVersions = page.items || [] }, 'Branding version history loaded.') },
    rollbackBranding (version) { return this.run(() => this.provider.rollbackBranding({ target_version: version }, { expectedVersion: this.branding.version }), `Branding restored from v${version}.`) },
    saveIdentity () { return this.run(() => this.provider.updateIdentityConfiguration({ oidc_enabled: this.identity.oidc_enabled, saml_enabled: this.identity.saml_enabled }, { expectedVersion: this.identity.version }), 'Identity configuration saved.') },
    toggleIntegration (integration) { return this.run(() => this.provider.updateIntegration(integration.integration_id, { active: !integration.active }, { expectedVersion: integration.version }), 'Integration updated.') },
    rotateIntegration (integration) { return this.run(() => this.provider.rotateIntegrationSecret(integration.integration_id, { expectedVersion: integration.version }), 'Integration secret rotated.') },
    publishBranding () { return this.run(() => this.provider.publishBranding({ expectedVersion: this.branding.version }), 'Branding published.') },
    saveContent () { return this.run(() => this.provider.updateAdminContent(this.selectedContent.content_key, { body: this.selectedContent.body }, { expectedVersion: this.selectedContent.version }), 'Content draft saved.') },
    previewContent () { return this.run(async () => { this.contentPreview = await this.provider.previewAdminContent(this.selectedContent.content_key, { body: this.selectedContent.body }) }, 'Content preview generated.') },
    loadContentVersions () { return this.run(async () => { const page = await this.provider.listAdminContentVersions(this.selectedContent.content_key, { page_size: 20 }); this.contentVersions = page.items || [] }, 'Content version history loaded.') },
    rollbackContent (version) { return this.run(() => this.provider.rollbackAdminContent(this.selectedContent.content_key, { target_version: version }, { expectedVersion: this.selectedContent.version }), `Content restored from v${version}.`) },
    publishContent () { return this.run(() => this.provider.publishAdminContent(this.selectedContent.content_key, { expectedVersion: this.selectedContent.version }), 'Content published.') },
    async loadHelp () { if (this.busy) return; this.busy = true; this.formErrors = []; try { const value = await this.provider.getAdminHelp(this.help.key, this.help.language); this.help = { ...this.help, body: value.body || '', version: value.version }; this.helpVersions = [] } catch (error) { this.fail(error) } finally { this.busy = false } },
    saveHelp () { return this.run(() => this.provider.updateAdminHelp(this.help.key, { body: this.help.body, language: this.help.language }, { expectedVersion: this.help.version }), 'Help draft saved.') },
    previewHelp () { return this.run(async () => { this.helpPreview = await this.provider.previewAdminHelp(this.help.key, { body: this.help.body, language: this.help.language }) }, 'Help preview generated.') },
    loadHelpVersions () { return this.run(async () => { const page = await this.provider.listAdminHelpVersions(this.help.key, { language: this.help.language, page_size: 20 }); this.helpVersions = page.items || [] }, 'Help version history loaded.') },
    rollbackHelp (version) { return this.run(() => this.provider.rollbackAdminHelp(this.help.key, { target_version: version }, this.help.language, { expectedVersion: this.help.version }), `Help restored from v${version}.`) },
    publishHelp () { return this.run(() => this.provider.publishAdminHelp(this.help.key, this.help.language, { expectedVersion: this.help.version }), 'Help published.') },
    resetCategory () { this.category = { code: '', labels: { EN: '', ES: '', VI: '' }, originalCode: '', active: true, version: null } },
    editCategory (item) { this.category = { code: item.code, labels: { EN: item.labels?.EN || '', ES: item.labels?.ES || '', VI: item.labels?.VI || '' }, originalCode: item.code, active: !!item.active, version: item.version } },
    saveCategory () { const labels = Object.fromEntries(Object.entries(this.category.labels).filter(([, value]) => value)); const input = { code: this.category.code, active: this.category.active, labels }; const updating = !!this.category.originalCode; return this.run(async () => { if (updating) await this.provider.updateAdminCategory(this.category.originalCode, input, { expectedVersion: this.category.version }); else await this.provider.createAdminCategory(input); this.resetCategory() }, updating ? 'Category updated.' : 'Category created.') },
    editCustomField (field) { this.customField = { key: field.key, originalKey: field.key, entity: field.entity, field_type: field.field_type, labels: { EN: field.labels?.EN || '', ES: field.labels?.ES || '', VI: field.labels?.VI || '' }, defaultValue: field.default === undefined ? '' : JSON.stringify(field.default), validation: field.validation ? JSON.stringify(field.validation) : '', choiceValues: (field.choice_values || []).join('\n'), required: !!field.required, active: !!field.active, version: field.version } },
    resetCustomField () { this.customField = { key: '', originalKey: '', entity: 'service_request', field_type: 'TEXT', labels: { EN: '', ES: '', VI: '' }, defaultValue: '', validation: '', choiceValues: '', required: false, active: true, version: null } },
    parseCustomFieldJSON (value, label, fallback) { if (!value) return fallback; try { return JSON.parse(value) } catch (_) { throw new Error(`${label} must contain valid JSON.`) } },
    saveCustomField () { const labels = Object.fromEntries(Object.entries(this.customField.labels).filter(([, value]) => value)); const choiceValues = this.customField.choiceValues.split('\n').map(value => value.trim()).filter(Boolean); const input = { key: this.customField.key, entity: this.customField.entity, field_type: this.customField.field_type, required: this.customField.required, active: this.customField.active, labels, default: this.parseCustomFieldJSON(this.customField.defaultValue, 'Default value', undefined), validation: this.parseCustomFieldJSON(this.customField.validation, 'Validation rules', undefined), ...(choiceValues.length ? { choice_values: choiceValues } : {}) }; return this.run(async () => { if (this.customField.originalKey) await this.provider.updateAdminCustomField(this.customField.originalKey, input, { expectedVersion: this.customField.version }); else await this.provider.createAdminCustomField(input); this.resetCustomField() }, 'Custom field saved.') },
    toggleWorkflow (workflow) { return this.run(() => workflow.active ? this.provider.deactivateWorkflow(workflow.workflow_id, { expectedVersion: workflow.version }) : this.provider.activateWorkflow(workflow.workflow_id, { expectedVersion: workflow.version }), `Workflow ${workflow.active ? 'deactivated' : 'activated'}.`) },
  },
}
</script>

